#include "MainComponent.h"
namespace {juce::String u(const char* s){return juce::String::fromUTF8(s);}}
class AutoEqPanel final : public juce::Component,private juce::Timer {
    StudioMain& owner;juce::Label title,help;juce::TextEditor report;juce::TextButton record,analyse,a,b,save,restore,load,cancel,listen;
public:
    explicit AutoEqPanel(StudioMain& main):owner(main){for(juce::Component* c:std::initializer_list<juce::Component*>{&title,&help,&report,&record,&analyse,&a,&b,&save,&restore,&load,&cancel,&listen})addAndMakeVisible(c);title.setText(u("HÁT MỘT BÀI → EQ RIÊNG CHO GIỌNG BẠN"),juce::dontSendNotification);title.setFont(juce::Font(21,juce::Font::bold));help.setText(u("1. Thu micro khô khi hát YouTube · 2. Dừng để tự phân tích · 3. Nghe A/B rồi lưu B\nKhông dùng beat/vocal ca sĩ khác. UPod Pro: Mixing OFF, Mic with DSP OFF."),juce::dontSendNotification);report.setMultiLine(true);report.setReadOnly(true);report.setScrollbarsShown(true);auto button=[](juce::TextButton& target,const char* text,std::function<void()> callback){target.setButtonText(u(text));target.onClick=std::move(callback);};button(record,"Thu bài để cân EQ",[this]{owner.recordAutoEq();});button(analyse,"Phân tích vocal đang chọn",[this]{owner.analyseAutoEq();});button(a,"A · EQ trước",[this]{owner.previewAutoEq(false);});button(b,"B · EQ đề xuất",[this]{owner.previewAutoEq(true);});button(save,"Lưu B làm EQ riêng",[this]{owner.saveAutoEq();});button(restore,"Về EQ đang lưu",[this]{owner.cancelAutoEq();});button(load,"Dùng EQ đã lưu",[this]{owner.loadAutoEq();});button(listen,"Nghe bản thu A/B",[this]{owner.listenAutoEq();});button(cancel,"Hủy phân tích",[this]{owner.cancelToolsWork();});setSize(790,650);startTimerHz(8);timerCallback();}
    ~AutoEqPanel() override{stopTimer();}
    void paint(juce::Graphics& g) override{g.fillAll(juce::Colour(0xff10151e));}
    void resized() override{int w=getWidth();title.setBounds(20,14,w-40,35);help.setBounds(20,51,w-40,58);record.setBounds(20,122,220,34);analyse.setBounds(250,122,250,34);load.setBounds(510,122,w-530,34);a.setBounds(20,168,160,34);b.setBounds(190,168,170,34);save.setBounds(370,168,210,34);restore.setBounds(590,168,w-610,34);report.setBounds(20,218,w-40,getHeight()-280);cancel.setBounds(20,getHeight()-48,180,30);listen.setBounds(215,getHeight()-48,220,30);}
    void timerCallback() override{const bool busy=owner.isBusy(),valid=owner.eqSuggestion.valid;record.setEnabled(!busy&&(!owner.engine.isRecording()||owner.eqRecording));record.setButtonText(owner.eqRecording?u("Dừng thu → Phân tích"):u("Thu bài để cân EQ"));analyse.setEnabled(owner.canEdit()&&owner.selected>=0);a.setEnabled(!busy&&valid);b.setEnabled(!busy&&valid);save.setEnabled(!busy&&valid);restore.setEnabled(!busy&&owner.eqPreview);load.setEnabled(!busy&&!owner.engine.isRecording());cancel.setEnabled(busy);listen.setEnabled(!busy&&!owner.engine.isRecording());listen.setButtonText(owner.engine.isEqListening()?u("Dừng nghe bản thu"):u("Nghe bản thu A/B"));const auto text=owner.eqStatus.isEmpty()?u("Chưa thay EQ. Bạn có thể hát cả bài; tool lấy các đoạn trải đều bản micro gốc để đề xuất mức chỉnh nhẹ.\n\nA/B giữ nguyên vang, compressor, Antares và nhạc. Mức nghe được bù ước tính để tránh chọn B chỉ vì to hơn. Đóng cửa sổ hoặc bấm Về EQ đang lưu sẽ bỏ phần nghe thử chưa lưu.\n\nNâng nốt trầm hay kéo nốt hát lên thuộc chỉnh cao độ, không phải EQ. Giọng đã vỡ do quá tải đầu vào cần giảm gain và thu lại."):owner.eqStatus;const auto current=busy?text+u("\n\nĐang xử lý: ")+juce::String(owner.toolsProgress()*100,0)+"%":text;if(report.getText()!=current)report.setText(current,false);}
};
juce::Component* createAutoEqPanel(StudioMain& owner){return new AutoEqPanel(owner);}
